// pg - bind the callsign (stops the injection) AND return a generic error (stops the schema leak)
try {
  await client.query('INSERT INTO promo_claims (callsign) VALUES ($1)', [callsign]);
  res.send('Callsign reserved');
} catch (err) {
  logger.error('reserve_callsign_failed', err); // real error stays server-side
  res.status(409).send('That callsign is unavailable');
}
// mysql2: conn.execute('INSERT INTO promo_claims (callsign) VALUES (?)', [callsign])

# Bind the callsign (stops injection); log the detail, return a generic error (stops the schema leak)
try:
    cur.execute("INSERT INTO promo_claims (callsign) VALUES (?)", (callsign,))
except sqlite3.IntegrityError:
    logger.exception("reserve_callsign_failed")  # detail to the log, not the user
    return Response("That callsign is unavailable", status=409)
# psycopg2 uses %s: cur.execute("... VALUES (%s)", (callsign,))

// PDO binds the callsign (stops injection); a generic error stops the schema leak
try {
    $stmt = $pdo->prepare('INSERT INTO promo_claims (callsign) VALUES (?)');
    $stmt->execute([$callsign]);
} catch (PDOException $e) {
    error_log($e->getMessage());        // detail stays in the server log
    http_response_code(409);
    echo 'That callsign is unavailable';
}

// PreparedStatement binds the callsign (stops injection); a generic reply stops the schema leak
try (PreparedStatement ps = conn.prepareStatement(
        "INSERT INTO promo_claims (callsign) VALUES (?)")) {
    ps.setString(1, callsign);
    ps.executeUpdate();
} catch (SQLException e) {
    log.error("reserve_callsign_failed", e);   // detail stays server-side
    resp.sendError(409, "That callsign is unavailable"); // generic message only
}

// Bind via SqlParameter (stops injection); return a generic error (stops the schema leak)
try {
    using var cmd = new SqlCommand("INSERT INTO promo_claims (callsign) VALUES (@c)", conn);
    cmd.Parameters.Add(new SqlParameter("@c", callsign));
    cmd.ExecuteNonQuery();
} catch (SqlException e) {
    _logger.LogError(e, "reserve_callsign_failed"); // server-side only
    return StatusCode(409, "That callsign is unavailable");
}

// Bind the callsign as $1 (stops injection); return a generic error (stops the schema leak)
